script:
mission_name = doc.custom_parent_mission

# =========================
# VALIDATIONS FIRST
# =========================

if not doc.custom_end_time:
    frappe.throw("Please Check Out before submitting.")

if not doc.custom_work_outcome:
    frappe.throw("Work Outcome is required before submit.")

if not doc.custom_client_signature:
    frappe.throw("Client Signature is required before submit.")

if not doc.custom_tech_signature:
    frappe.throw("Tech Signature is required before submit.")

if not doc.custom_signatory_name:
    frappe.throw("Signatory Name is required before submit.")

if doc.custom_work_outcome == "Work Completed":
    if not doc.custom_quality_score:
        frappe.throw("Quality Rating is required when work is completed.")

    if not doc.custom_hse_score:
        frappe.throw("HSE Rating is required when work is completed.")

if not mission_name:
    frappe.throw("Parent Mission is missing.")

mission = frappe.get_doc("Tech Mission", mission_name)

# =========================
# TECHNICIAN HOURS
# =========================

tech_count = 1
if doc.get("custom_intervention_team"):
    tech_count = len(doc.custom_intervention_team)

actual_hours = doc.custom_hours_worked or 0

if mission.get("custom_count_each_technician"):
    billable_hours = actual_hours * tech_count
else:
    billable_hours = actual_hours

# =========================
# ADD MISSION HISTORY
# =========================

exists = False
for row in mission.get("custom_intervention_table") or []:
    if row.get("custom_intervention_reference") == doc.name:
        exists = True
        break

status_map = {
    "Work Completed": "Completed",
    "Continue Work": "Ongoing",
    "Waiting Parts": "Waiting Parts",
    "Waiting Client": "Waiting Client",
    "Could Not Complete": "Ongoing"
}

if not exists:
    child = {
        "custom_date": frappe.utils.now_datetime(),
        "custom_intervention_reference": doc.name,
        "custom_technician": doc.custom_technician,
        "custom_hours": actual_hours,
        "custom_status": status_map.get(doc.custom_work_outcome, "In Progress"),
        "custom_work_progress": doc.custom_work_progress
    }

    if frappe.get_meta("Mission Intervention Log").has_field("custom_technician_count"):
        child["custom_technician_count"] = tech_count

    if frappe.get_meta("Mission Intervention Log").has_field("custom_billable_hours"):
        child["custom_billable_hours"] = billable_hours

    mission.append("custom_intervention_table", child)

# =========================
# RECALCULATE MISSION TOTALS
# =========================

total_actual = 0
total_billable = 0

for row in mission.get("custom_intervention_table") or []:
    total_actual += row.get("custom_hours") or 0

    if row.get("custom_billable_hours") is not None:
        total_billable += row.get("custom_billable_hours") or 0
    else:
        total_billable += row.get("custom_hours") or 0

if mission.meta.has_field("custom_total_actual_hours"):
    mission.custom_total_actual_hours = total_actual

if mission.meta.has_field("custom_total_billable_hours"):
    mission.custom_total_billable_hours = total_billable

if mission.meta.has_field("custom_last_intervention_date"):
    mission.custom_last_intervention_date = frappe.utils.now_datetime()

if mission.meta.has_field("custom_intervention_count"):
    mission.custom_intervention_count = len(mission.get("custom_intervention_table") or [])

# =========================
# OUTCOME MAPPING
# =========================

outcome = doc.custom_work_outcome
ticket_status = None
hold_reason = None

if outcome == "Work Completed":
    mission.custom_mission_status = "Completed"
    ticket_status = "Resolved"
    hold_reason = ""

elif outcome == "Continue Work":
    mission.custom_mission_status = "Ongoing"
    ticket_status = "In Progress"
    hold_reason = ""

elif outcome == "Waiting Parts":
    mission.custom_mission_status = "Ongoing"
    ticket_status = "On Hold"
    hold_reason = "Awaiting Parts"

elif outcome == "Waiting Client":
    mission.custom_mission_status = "Ongoing"
    ticket_status = "On Hold"
    hold_reason = "Awaiting Client"

elif outcome == "Could Not Complete":
    mission.custom_mission_status = "Ongoing"
    ticket_status = "On Hold"
    hold_reason = "Could Not Complete"

else:
    mission.custom_mission_status = "Ongoing"
    ticket_status = "In Progress"
    hold_reason = ""

mission.save(ignore_permissions=True)

# =========================
# CLOSE TECH MISSION TODOS
# =========================

if mission.custom_mission_status == "Completed":
    todos = frappe.get_all(
        "ToDo",
        filters={
            "reference_type": "Tech Mission",
            "reference_name": mission.name,
            "status": "Open"
        },
        pluck="name"
    )

    for todo_name in todos:
        todo = frappe.get_doc("ToDo", todo_name)
        todo.status = "Closed"
        todo.description = (todo.description or "") + "<br><br><b>Closed because mission was completed.</b>"
        todo.save(ignore_permissions=True)

# =========================
# UPDATE SERVICE TICKET
# =========================

if doc.custom_service_ticket:
    ticket = frappe.get_doc("Service Ticket", doc.custom_service_ticket)

    if ticket_status:
        ticket.custom_ticket_status = ticket_status

    if ticket.meta.has_field("custom_hold_reason"):
        ticket.custom_hold_reason = hold_reason or ""

    if outcome == "Work Completed":
        if ticket.meta.has_field("custom_resolution_details"):
            ticket.custom_resolution_details = doc.custom_work_progress

        if ticket.meta.has_field("custom_resolution_date"):
            ticket.custom_resolution_date = frappe.utils.now_datetime()

        if ticket.meta.has_field("custom_resolved_by"):
            ticket.custom_resolved_by = frappe.session.user

        if ticket.meta.has_field("custom_resolution_source_mi"):
            ticket.custom_resolution_source_mi = doc.name

    ticket.save(ignore_permissions=True)

ticket_id = doc.custom_service_ticket

if ticket_id:
    try:
        ticket = frappe.get_doc("Service Ticket", ticket_id)

        #ticket.custom_ticket_status = "On Hold"
        if ticket.custom_ticket_status != "Resolved":
            ticket.custom_ticket_status = "On Hold"
            ticket.custom_hold_reason = "Awaiting Quote Approval"
            ticket.custom_commercial_status = "Quote Sent"
            ticket.custom_requires_parts = doc.custom_requires_parts or 0

        exists = False
        for row in ticket.get("custom_commercial_references") or []:
            if row.custom_reference_type == "Quotation" and row.custom_reference_name == doc.name:
                exists = True
                row.custom_status = doc.status
                row.custom_amount = doc.grand_total or 0
                row.custom_posting_date = doc.transaction_date
                row.custom_remarks = "Quotation submitted"

        if not exists:
            ticket.append("custom_commercial_references", {
                "custom_reference_type": "Quotation",
                "custom_reference_name": doc.name,
                "custom_status": doc.status,
                "custom_amount": doc.grand_total or 0,
                "custom_posting_date": doc.transaction_date,
                "custom_remarks": "Quotation submitted"
            })

        ticket.save(ignore_permissions=True)

    except Exception as e:
        frappe.log_error(str(e), "Quotation Service Ticket Sync Failed")

ticket_id = doc.custom_service_ticket
requires_parts = doc.custom_requires_parts or 0

if not ticket_id:
    for item in doc.items:
        if item.prevdoc_docname:
            vals = frappe.db.get_value(
                "Quotation",
                item.prevdoc_docname,
                ["custom_service_ticket", "custom_requires_parts"],
                as_dict=True
            )
            if vals:
                ticket_id = vals.custom_service_ticket
                requires_parts = vals.custom_requires_parts or 0
                break

if ticket_id:
    try:
        ticket = frappe.get_doc("Service Ticket", ticket_id)

        was_resolved = ticket.custom_ticket_status == "Resolved"

        ticket.custom_requires_parts = requires_parts

        if requires_parts:
            if not was_resolved:
                ticket.custom_ticket_status = "On Hold"
                ticket.custom_hold_reason = "Awaiting Parts"
                ticket.custom_commercial_status = "Awaiting Parts"
            else:
                ticket.custom_ticket_status = "Resolved"
                ticket.custom_hold_reason = ""
                ticket.custom_commercial_status = "To be Invoiced"

        else:
            if was_resolved:
                ticket.custom_ticket_status = "Resolved"
                ticket.custom_hold_reason = ""
                ticket.custom_commercial_status = "To be Invoiced"
            else:
                ticket.custom_ticket_status = "Ready for Planning"
                ticket.custom_hold_reason = ""
                ticket.custom_commercial_status = "Ready for Planning"

        exists = False

        for row in ticket.get("custom_commercial_references") or []:
            if row.custom_reference_type == "Sales Order" and row.custom_reference_name == doc.name:
                exists = True
                row.custom_status = doc.status
                row.custom_amount = doc.grand_total or 0
                row.custom_posting_date = doc.transaction_date
                row.custom_remarks = "Sales Order submitted"

        if not exists:
            ticket.append("custom_commercial_references", {
                "custom_reference_type": "Sales Order",
                "custom_reference_name": doc.name,
                "custom_status": doc.status,
                "custom_amount": doc.grand_total or 0,
                "custom_posting_date": doc.transaction_date,
                "custom_remarks": "Sales Order submitted"
            })

        ticket.save(ignore_permissions=True)

        if not doc.custom_service_ticket:
            frappe.db.set_value("Sales Order", doc.name, "custom_service_ticket", ticket_id)

        if doc.custom_requires_parts != requires_parts:
            frappe.db.set_value("Sales Order", doc.name, "custom_requires_parts", requires_parts)

    except Exception as e:
        frappe.log_error(str(e), "Sales Order Service Ticket Sync Failed")

ticket_id = doc.custom_service_ticket

if not ticket_id:
    for item in doc.items:
        if item.sales_order:
            ticket_id = frappe.db.get_value(
                "Sales Order",
                item.sales_order,
                "custom_service_ticket"
            )
            if ticket_id:
                break

if ticket_id:
    try:
        ticket = frappe.get_doc("Service Ticket", ticket_id)

        ticket.custom_ticket_status = "On Hold"
        ticket.custom_hold_reason = "Awaiting Parts"
        ticket.custom_commercial_status = "Awaiting Parts"
        ticket.custom_requires_parts = 1

        exists = False
        for row in ticket.get("custom_commercial_references") or []:
            if row.custom_reference_type == "Purchase Order" and row.custom_reference_name == doc.name:
                exists = True
                row.custom_status = doc.status
                row.custom_amount = doc.grand_total or 0
                row.custom_posting_date = doc.transaction_date
                row.custom_remarks = "Purchase Order submitted"

        if not exists:
            ticket.append("custom_commercial_references", {
                "custom_reference_type": "Purchase Order",
                "custom_reference_name": doc.name,
                "custom_status": doc.status,
                "custom_amount": doc.grand_total or 0,
                "custom_posting_date": doc.transaction_date,
                "custom_remarks": "Purchase Order submitted"
            })

        ticket.save(ignore_permissions=True)

        if not doc.custom_service_ticket:
            frappe.db.set_value("Purchase Order", doc.name, "custom_service_ticket", ticket_id)

    except Exception as e:
        frappe.log_error(str(e), "Purchase Order Service Ticket Sync Failed")

ticket_id = doc.custom_service_ticket

if not ticket_id:
    for item in doc.items:
        if item.purchase_order:
            ticket_id = frappe.db.get_value(
                "Purchase Order",
                item.purchase_order,
                "custom_service_ticket"
            )
            if ticket_id:
                break

if ticket_id:
    try:
        ticket = frappe.get_doc("Service Ticket", ticket_id)

        ticket.custom_ticket_status = "Ready for Planning"
        ticket.custom_hold_reason = ""
        ticket.custom_commercial_status = "Ready for Planning"
        ticket.custom_requires_parts = 1

        exists = False
        for row in ticket.get("custom_commercial_references") or []:
            if row.custom_reference_type == "Purchase Receipt" and row.custom_reference_name == doc.name:
                exists = True
                row.custom_status = doc.status
                row.custom_amount = doc.grand_total or 0
                row.custom_posting_date = doc.posting_date
                row.custom_remarks = "Purchase Receipt submitted"

        if not exists:
            ticket.append("custom_commercial_references", {
                "custom_reference_type": "Purchase Receipt",
                "custom_reference_name": doc.name,
                "custom_status": doc.status,
                "custom_amount": doc.grand_total or 0,
                "custom_posting_date": doc.posting_date,
                "custom_remarks": "Purchase Receipt submitted"
            })

        ticket.save(ignore_permissions=True)

        if not doc.custom_service_ticket:
            frappe.db.set_value("Purchase Receipt", doc.name, "custom_service_ticket", ticket_id)

    except Exception as e:
        frappe.log_error(str(e), "Purchase Receipt Service Ticket Sync Failed")

ticket_id = doc.custom_service_ticket

if not ticket_id:
    for item in doc.items:
        if item.against_sales_order:
            ticket_id = frappe.db.get_value(
                "Sales Order",
                item.against_sales_order,
                "custom_service_ticket"
            )
            if ticket_id:
                break

if ticket_id:
    try:
        ticket = frappe.get_doc("Service Ticket", ticket_id)

        if ticket.custom_ticket_status not in ["Resolved", "Closed"]:
            ticket.custom_ticket_status = "Ready for Planning"

        ticket.custom_hold_reason = ""

        if ticket.custom_commercial_status in ["Awaiting Parts", "Quote Approved"]:
            ticket.custom_commercial_status = "Ready for Planning"

        exists = False
        for row in ticket.get("custom_commercial_references") or []:
            if row.custom_reference_type == "Delivery Note" and row.custom_reference_name == doc.name:
                exists = True
                row.custom_status = doc.status
                row.custom_amount = doc.grand_total or 0
                row.custom_posting_date = doc.posting_date
                row.custom_remarks = "Delivery Note submitted"

        if not exists:
            ticket.append("custom_commercial_references", {
                "custom_reference_type": "Delivery Note",
                "custom_reference_name": doc.name,
                "custom_status": doc.status,
                "custom_amount": doc.grand_total or 0,
                "custom_posting_date": doc.posting_date,
                "custom_remarks": "Delivery Note submitted"
            })

        ticket.save(ignore_permissions=True)

        if not doc.custom_service_ticket:
            frappe.db.set_value("Delivery Note", doc.name, "custom_service_ticket", ticket_id)

    except Exception as e:
        frappe.log_error(str(e), "Delivery Note Service Ticket Sync Failed")

ticket_id = doc.custom_service_ticket

if not ticket_id:
    for item in doc.items:
        if item.sales_order:
            ticket_id = frappe.db.get_value(
                "Sales Order",
                item.sales_order,
                "custom_service_ticket"
            )
            if ticket_id:
                break

if ticket_id:
    try:
        ticket = frappe.get_doc("Service Ticket", ticket_id)

        ticket.custom_commercial_status = "Invoiced"

        exists = False
        for row in ticket.get("custom_commercial_references") or []:
            if row.custom_reference_type == "Sales Invoice" and row.custom_reference_name == doc.name:
                exists = True
                row.custom_status = doc.status
                row.custom_amount = doc.grand_total or 0
                row.custom_posting_date = doc.posting_date
                row.custom_remarks = "Sales Invoice submitted"

        if not exists:
            ticket.append("custom_commercial_references", {
                "custom_reference_type": "Sales Invoice",
                "custom_reference_name": doc.name,
                "custom_status": doc.status,
                "custom_amount": doc.grand_total or 0,
                "custom_posting_date": doc.posting_date,
                "custom_remarks": "Sales Invoice submitted"
            })

        ticket.save(ignore_permissions=True)

        if not doc.custom_service_ticket:
            frappe.db.set_value("Sales Invoice", doc.name, "custom_service_ticket", ticket_id)

    except Exception as e:
        frappe.log_error(str(e), "Sales Invoice Service Ticket Sync Failed")

for ref in doc.get("references") or []:

    if ref.reference_doctype != "Sales Invoice":
        continue

    if not ref.reference_name:
        continue

    ticket_id = frappe.db.get_value(
        "Sales Invoice",
        ref.reference_name,
        "custom_service_ticket"
    )

    if not ticket_id:
        continue

    if not frappe.db.exists("Service Ticket", ticket_id):
        continue

    outstanding = frappe.db.get_value(
        "Sales Invoice",
        ref.reference_name,
        "outstanding_amount"
    ) or 0

    ticket = frappe.get_doc("Service Ticket", ticket_id)

    if outstanding <= 0:
        ticket.custom_commercial_status = "Paid"
        payment_status = "Paid"
    else:
        ticket.custom_commercial_status = "Partly Paid"
        payment_status = "Partly Paid"

    exists = False

    for row in ticket.get("custom_commercial_references") or []:
        if (
            row.custom_reference_type == "Payment Entry"
            and row.custom_reference_name == doc.name
        ):
            exists = True
            row.custom_status = payment_status
            row.custom_amount = doc.paid_amount or 0
            row.custom_posting_date = doc.posting_date
            row.custom_remarks = "Payment Entry submitted"

    if not exists:
        ticket.append("custom_commercial_references", {
            "custom_reference_type": "Payment Entry",
            "custom_reference_name": doc.name,
            "custom_status": payment_status,
            "custom_amount": doc.paid_amount or 0,
            "custom_posting_date": doc.posting_date,
            "custom_remarks": "Payment Entry submitted"
        })

    ticket.save(ignore_permissions=True)

ticket_id = doc.get("custom_service_ticket")

if ticket_id and frappe.db.exists("Service Ticket", ticket_id):

    outstanding = doc.outstanding_amount or 0

    ticket = frappe.get_doc("Service Ticket", ticket_id)

    if outstanding <= 0 and doc.docstatus == 1:
        ticket.custom_commercial_status = "Paid"

    elif outstanding > 0 and doc.docstatus == 1:
        if doc.paid_amount and doc.paid_amount > 0:
            ticket.custom_commercial_status = "Partly Paid"
        else:
            ticket.custom_commercial_status = "Invoiced"

    ticket.save(ignore_permissions=True)

if (
    doc.custom_planned_starttime
    and doc.custom_planned_endtime
    and doc.custom_planned_starttime >= doc.custom_planned_endtime
):
    frappe.throw("Planned End Time must be after Planned Start Time.")
